<script>
    import { each } from "svelte/internal";
    import { formatLocale } from "d3-format";

    export let type = "number";
    export let id;
    export let row;
    export let dataCharts;
    export let dataText;

    $: key = row.measure;
    // $: console.log("row", row);
    // $: console.log("key", key);
    // console.log("dataCharts", dataCharts);

    $: thisChart = dataCharts.map((e) => e[key]).filter((e) => e);
    //   let max = row.yaxisend;
    //   let min = row.yaxisstart;
    //   let range = max - min;

    // console.log(thisChart, row.enddate);

    let chartWidth = 300,
        height = 110;
    let el;

    // UK locale so "$" in a format string renders as £ rather than $
    const ukLocale = formatLocale({
        decimal: ".",
        thousands: ",",
        grouping: [3],
        currency: ["£", ""]
    });

    const ukFormat = ukLocale.format("$,.0f");

    $: formattedValue = row.directLabelUnit?.includes("£")
        ? ukFormat(thisChart)
        : (Math.round(thisChart * 10) / 10).toFixed(1);

    $: suffix = row.directLabelUnit?.includes("£")
        ? ""
        : row.directLabelUnit?.includes("%")
        ? row.directLabelUnit
        : " " + row.directLabelUnit;
</script>

<div class="graphic" {id} bind:this={el} bind:clientWidth={chartWidth}>
    <!-- Chart heading text -->
    <div class="chartContainer">
        <p class="headingText">{row.headingtext}</p>
    </div>

    <svg class="chartDrawing" width="281">
        <!-- This bit draws the chart background -->
        <rect
            class="chartBackground"
            x="35"
            width={chartWidth - 104}
            height="110"
        ></rect>

        <!-- Big number and end date-->
        <text class="bigNo" x={chartWidth / 2 - 12} y={height / 2 + 6}>
            {formattedValue}{suffix}
        </text>
        <text
            class="bigDate"
            x={chartWidth / 2 - 12}
            y={height / 0.95}
            font-size={chartWidth < 290 ? "20px" : "22px"}
            >{row.enddate
                .replace("Sep-", "Sept ")
                .replace("Jun-", "June ")
                .replace("Jul-", "July ")
                .replace("-", " ")}</text
        >
    </svg>
    <p class="updated">Updated: {row.update
            .replace(/^0/, "")
            .replace("Sep-", "Sept ")
            .replace("Jun-", "June ")
            .replace("Jul-", "July ")
            .replace("-", " ")
            .replace(/\b(\d{2})$/, "20$1")}</p>
</div>